#!/usr/bin/env bash
# Adds the Illustrated (pastel isometric) map mode + 3 landmark SVGs to the kabul-map repo.
# Run from the repo root (kabul-map-main) or from kabul-apple or kabul-apple/frontend:  bash apply-illustrated.sh
set -euo pipefail
if [ -d kabul-apple/frontend ]; then cd kabul-apple/frontend
elif [ -d frontend ]; then cd frontend
elif [ -f components/KabulMap.tsx ]; then :
else echo "Run this from the kabul-map repo (could not find the frontend folder)." >&2; exit 1; fi
mkdir -p public/landmarks
