    t=t[:i]+"""// ---- Illustrated mode: pastel, inked, isometric look (cream ground, pale roads, painted roofs) ----
const INK = "#2d3454";
const ROOFS = ["#f2eee4", "#fbf9f3", "#d9604a", "#3b4a7a", "#a9c9a0", "#e8c25a", "#6fb3a8", "#c4624a"];
const illustrated: Record<string, Record<string, any>> = {
  bg: { "background-color": "#f3eee3" },
  landcover: { "fill-color": ["match", ["get", "class"], "wood", "#a9d18f", "grass", "#c4e0ac", "wetland", "#bfdcb6", "farmland", "#ece8d2", "sand", "#efe3c4", "#f3eee3"] },
  park: { "fill-color": "#b4d99c", "fill-opacity": 1 },
  landuse: { "fill-color": ["match", ["get", "class"], "hospital", "#f3d9d2", "school", "#efe6cc", "college", "#efe6cc", "cemetery", "#bfdcb6", "industrial", "#e6e1d6", "#c4e0ac"] },
  water: { "fill-color": "#8fc0e8" },
  waterway: { "line-color": "#8fc0e8" },
  building: { "fill-opacity": 0 },
  "minor-case": { "line-color": "#d2ccbd" }, minor: { "line-color": "#ebe7dc" },
  "street-case": { "line-color": "#cbc5b5" }, street: { "line-color": "#efebe0" },
  "main-case": { "line-color": "#bdb6a3" }, main: { "line-color": "#f5f1e4" },
  "motorway-case": { "line-color": "#b3ac98" }, motorway: { "line-color": "#f5f1e4" },
  "building-3d": {
    "fill-extrusion-color": ["match", ["%", ["coalesce", ["id"], 0], 8], ...ROOFS.flatMap((c, n) => (n < 7 ? [n, c] : [])), ROOFS[7]],
    "fill-extrusion-opacity": 1,
  },
};
const original: Record<string, any> = {};
function setPaint(map: MLMap, id: string, prop: string, value: any) {
  if (!map.getLayer(id)) return;
  const k = `${id}|${prop}`;
  if (!(k in original)) original[k] = map.getPaintProperty(id, prop);
  map.setPaintProperty(id, prop, value);
}
function restorePaint(map: MLMap) {
  for (const k of Object.keys(original)) {
    const [id, prop] = k.split("|");
    if (map.getLayer(id)) map.setPaintProperty(id, prop, original[k]);
  }
}

export function applyMode(map: MLMap, mode: Mode) {
  const sat = mode === "satellite";
  const ill = mode === "illustrated";
  restorePaint(map);
  if (ill) for (const [id, props] of Object.entries(illustrated)) for (const [prop, v] of Object.entries(props)) setPaint(map, id, prop, v);
  if (map.getLayer("building-3d")) map.setLayerZoomRange("building-3d", ill ? 14 : 15, 24);
  for (const l of map.getStyle().layers) {
    const m: any = (l as any).metadata;
    if (m?.g === "base") map.setLayoutProperty(l.id, "visibility", sat ? "none" : "visible");
    if (m?.g === "sat") map.setLayoutProperty(l.id, "visibility", sat ? "visible" : "none");
    if (m?.g === "ill-only") map.setLayoutProperty(l.id, "visibility", ill ? "visible" : "none");
    if (m?.g === "label") {
      map.setPaintProperty(l.id, "text-color", sat ? "#ffffff" : ill ? INK : m.c);
      map.setPaintProperty(l.id, "text-halo-color", sat ? "rgba(0,0,0,0.65)" : ill ? "rgba(245,241,232,0.95)" : "rgba(255,255,255,0.9)");
    }
  }
  if (map.getLayer("mask")) map.setPaintProperty("mask", "fill-color", sat ? "#1c1c1e" : ill ? "#e8e2d3" : "#e5e3de");
}
"""
