    const items = LANDMARKS.map((l) => {
      const el = document.createElement("img");
      el.src = `/landmarks/${l.file}.svg`;
      el.alt = l.name;
      el.draggable = false;
      el.style.cssText = "pointer-events:none;max-width:none;user-select:none";
