      items.forEach(({ el, marker }) => {
        el.style.width = `${w}px`;
        el.style.height = `${h}px`;
        marker.setOffset([-w / 2, -h * 0.66]);
      });
    };
    fit();
    map.on("zoom", fit);
    return () => { map.off("zoom", fit); items.forEach((i) => i.marker.remove()); };
  }, [ready, buildings3dVisible]);

